import fetch from"node-fetch";const API="https://api.escuelajs.co/api/v1";function postData(t,o){return fetch(t,{method:"POST",mode:"cors",credentials:"same-origin",headers:{"Content-Type":"application/json"},body:JSON.stringify(o)})}const data={title:"204",price:204,description:"A description",categoryId:1,images:["https://placehold.co/600x400"]};postData(`${API}/products`,data).then((t=>t.json())).then((t=>console.log(t)));